create table public.ngo_engine_keys(key_hash text primary key check(key_hash ~ '^[a-f0-9]{64}$'));
create table public.ngo_field_notes(id uuid primary key default gen_random_uuid(),owner_hash text not null,client_id uuid not null,note_date date not null,org text not null,notes jsonb not null,created_at timestamptz not null default now(),unique(owner_hash,client_id));
create index ngo_field_notes_owner_date on public.ngo_field_notes(owner_hash,note_date);
create table public.ngo_automation_settings(owner_hash text primary key,org text not null,weekly_enabled boolean not null default false,monthly_enabled boolean not null default false,coordinator_email text not null default '',coordinator_whatsapp text not null default '',updated_at timestamptz not null default now());
create table public.ngo_report_drafts(id uuid primary key default gen_random_uuid(),owner_hash text not null,period text not null,org text not null,content text not null,created_at timestamptz not null default now(),unique(owner_hash,period));
do $$ declare t text; begin foreach t in array array['ngo_engine_keys','ngo_field_notes','ngo_automation_settings','ngo_report_drafts'] loop execute format('alter table public.%I enable row level security',t);execute format('revoke all on public.%I from anon,authenticated',t);execute format('grant select,insert,update,delete on public.%I to service_role',t);end loop;end $$;
